50	__device__ __constant__ int kDecOffsets[kDecNumTensors] = {
51	    0, 202752, 210944, 12793856, 12800000, 16994304, 16996352, 16998400, 17000448, 17002496,
52	    17004544, 33781760, 33789952, 50567168, 50569216, 63152128, 63158272, 67352576, 67354624, 67356672,
53	    67358720, 67360768, 67362816, 84140032, 84148224, 100925440, 100927488, 100929536, 100931584, 101134336
54	};
55	
56	// Per-tensor element sizes (numel), same order.
57	__device__ __constant__ int kDecSizes[kDecNumTensors] = {
58	    202752, 8192, 12582912, 6144, 4194304, 2048, 2048, 2048, 2048, 2048,
59	    16777216, 8192, 16777216, 2048, 12582912, 6144, 4194304, 2048, 2048, 2048,
60	    2048, 2048, 16777216, 8192, 16777216, 2048, 2048, 2048, 202752, 99
61	};
