63	static_assert(kDecNumTensors == 30,
64	              "decoder_layout: tensor count drifted. Regenerate via "
65	              "megakernel_codegen.py --decoder-layout.");
66	static_assert(kDecTotalElems == 101134435,
67	              "decoder_layout: total param count drifted. Regenerate.");
