69	// Host-constexpr mirrors so a sum/offset cross-check folds at compile time (a
70	// __constant__ array can't be folded in a constexpr). These guarantee
71	// offsets/sizes/total agree.
72	namespace dec_layout_check {
73	constexpr int kSizes[kDecNumTensors] = {
74	    202752, 8192, 12582912, 6144, 4194304, 2048, 2048, 2048, 2048, 2048,
75	    16777216, 8192, 16777216, 2048, 12582912, 6144, 4194304, 2048, 2048, 2048,
76	    2048, 2048, 16777216, 8192, 16777216, 2048, 2048, 2048, 202752, 99
77	};
78	constexpr int kOffsets[kDecNumTensors] = {
79	    0, 202752, 210944, 12793856, 12800000, 16994304, 16996352, 16998400, 17000448, 17002496,
80	    17004544, 33781760, 33789952, 50567168, 50569216, 63152128, 63158272, 67352576, 67354624, 67356672,
81	    67358720, 67360768, 67362816, 84140032, 84148224, 100925440, 100927488, 100929536, 100931584, 101134336
82	};
83	constexpr int64_t sum_sizes() {
84	    int64_t s = 0;
85	    for (int i = 0; i < kDecNumTensors; ++i) s += kSizes[i];
86	    return s;
87	}
88	constexpr bool offsets_consistent() {
89	    int64_t acc = 0;
90	    for (int i = 0; i < kDecNumTensors; ++i) {
91	        if (kOffsets[i] != (int)acc) return false;
92	        acc += kSizes[i];
93	    }
94	    return true;
95	}
96	// Largest per-tensor numel (folds at compile time from the layout table). The
97	// d-INDEPENDENT optimizer tails (SuperGrok2's per-CTA workspace stride, sized for
98	// the LARGEST tensor) re-derive their capacity from THIS instead of a d=128-pinned
99	// 65536 literal, so the SAME tail code is correct at every ladder width.
100	constexpr int max_size() {
101	    int m = 0;
102	    for (int i = 0; i < kDecNumTensors; ++i) if (kSizes[i] > m) m = kSizes[i];
103	    return m;
104	}
105	static_assert(sum_sizes() == kDecTotalElems,
106	              "decoder_layout: sum(kDecSizes) != kDecTotalElems. Regenerate.");
107	static_assert(offsets_consistent(),
108	              "decoder_layout: kDecOffsets[i] != sum(kDecSizes[0..i)). Regenerate.");
109	}  // namespace dec_layout_check
